package direwolf

// These tests put the demodulators to work with the rest of the TNC: frames
// generated by the tone generator and layer 2 sender, or decoded through the
// multi-modem and samoyed-atest. The demodulators' own unit tests are in
// internal/demod.

import (
	"fmt"
	"math/rand/v2"
	"path/filepath"
	"strconv"
	"testing"

	"github.com/doismellburning/samoyed/internal/ax25"
	"github.com/doismellburning/samoyed/internal/dwcore"
	"github.com/doismellburning/samoyed/internal/hdlc"
	"github.com/doismellburning/samoyed/internal/linecode"
	"github.com/doismellburning/samoyed/internal/phy"
	"github.com/spf13/pflag"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// generateFrames has the tone generator send each of frames with the modem
// audioConfig sets up for channel 0, and returns the 16 bit samples it makes.
func generateFrames(t *testing.T, audioConfig *RadioConfig, frames []*ax25.Packet) []int {
	t.Helper()

	const channel = 0

	var sink = new(byteSink)

	var sender = NewLayer2Sender(channel, audioConfig.achan[channel].layer2Config, NewToneGenerator(channel, audioConfig, 50, sink), 0, 0)

	sender.SendPreamblePostamble(32, false)

	for _, pp := range frames {
		sender.SendFrame(pp, false)
		sender.SendPreamblePostamble(4, false)
	}

	sender.SendPreamblePostamble(16, true)

	require.NotEmpty(t, sink.data)
	require.Zero(t, len(sink.data)%2, "16 bit samples come in pairs of bytes")

	var samples = make([]int, 0, len(sink.data)/2)
	for _, sample := range decodeMono16(sink.data) {
		samples = append(samples, int(sample))
	}

	return samples
}

// demodulateFrames runs samples through the demodulators audioConfig sets up
// for channel 0, and returns the frames they hand on and the receiver that
// holds the demodulators.
func demodulateFrames(t *testing.T, audioConfig *RadioConfig, samples []int) ([]*ax25.Packet, *Layer2Receiver) {
	t.Helper()

	const channel = 0

	var sink = new(recordingReceiveSink)

	var receiver, receiverErr = multi_modem_init(audioConfig, 0, 0, sink)
	require.NoError(t, receiverErr)

	for _, sam := range samples {
		receiver.ProcessSample(channel, sam)
	}

	// Enough silence afterwards for the last frame to be picked from the
	// candidates, however many slicers heard it.
	for range 2 * receiver.modems[channel].processAge {
		receiver.ProcessSample(channel, 0)
	}

	return sink.frames, receiver
}

func new9600TestRadioConfig(sampleRate int, profiles string, upsample int) *RadioConfig {
	var audioConfig = newTestRadioConfig(0, MODEM_SCRAMBLE, 9600, 0, 0, sampleRate)
	audioConfig.adev[0].defined = 1
	audioConfig.achan[0].NumFreq = 1
	audioConfig.achan[0].Profiles = profiles
	audioConfig.achan[0].Upsample = upsample
	audioConfig.achan[0].fix_bits = RETRY_NONE

	return audioConfig
}

// What the tone generator sends as G3RUH at 9600 baud, the 9600 demodulator
// decodes back, however the samples are upsampled, and with one slicer or
// several.
func TestDemod9600RoundTrip(t *testing.T) {
	t.Parallel()

	for _, tc := range []struct {
		name       string
		sampleRate int
		profiles   string
		upsample   int
	}{
		{"single slicer, default upsample", 48000, "-", 0},
		{"multiple slicers, default upsample", 48000, "+", 0},
		{"upsample 1", 96000, "-", 1},
		{"upsample 2", 96000, "-", 2},
		{"upsample 4", 44100, "-", 4},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			var texts = []string{
				"Q1TEST>Q2TEST:Hello at 9600 baud",
				"Q1TEST>Q2TEST,WIDE1-1:>A second frame, somewhat longer than the first",
			}

			var frames = make([]*ax25.Packet, 0, len(texts))

			for _, text := range texts {
				var pp = ax25.FromText(text, true)
				require.NotNil(t, pp)

				frames = append(frames, pp)
			}

			var samples = generateFrames(t, new9600TestRadioConfig(tc.sampleRate, tc.profiles, tc.upsample), frames)

			var audioConfig = new9600TestRadioConfig(tc.sampleRate, tc.profiles, tc.upsample)
			var got, receiver = demodulateFrames(t, audioConfig, samples)

			require.Len(t, got, len(texts))

			for i, pp := range got {
				assert.Equal(t, texts[i], pp.FormatAddrs()+string(pp.Info()))
			}

			var d = receiver.demods[0]
			require.NotNil(t, d)

			if tc.profiles == "+" {
				assert.Equal(t, MAX_SLICERS, d.NumSlicers())
			} else {
				assert.Equal(t, 1, d.NumSlicers())
			}

			// The signal level seen along the way was captured for reporting.
			var level = d.AudioLevel(0)
			assert.Positive(t, level.Mark)
			assert.Negative(t, level.Space)
		})
	}
}

// Silence decodes to nothing.
func TestDemod9600Silence(t *testing.T) {
	t.Parallel()

	var audioConfig = new9600TestRadioConfig(48000, "-", 0)

	var got, _ = demodulateFrames(t, audioConfig, make([]int, 48000/10))

	assert.Empty(t, got)
}

// afskTestCase is an AFSK modem set up one of the ways the round trip tests
// try.
type afskTestCase struct {
	name       string
	baud       int
	mark       int
	space      int
	sampleRate int
	profiles   string
	decimate   int // 0 lets demod.New choose.
}

func (tc afskTestCase) radioConfig() *RadioConfig {
	var audioConfig = newTestRadioConfig(0, MODEM_AFSK, tc.baud, tc.mark, tc.space, tc.sampleRate)
	audioConfig.adev[0].defined = 1
	audioConfig.achan[0].NumFreq = 1
	audioConfig.achan[0].Profiles = tc.profiles
	audioConfig.achan[0].Decimate = tc.decimate
	audioConfig.achan[0].fix_bits = RETRY_NONE

	return audioConfig
}

// afskTestFrames is count frames, each saying which it is.
func afskTestFrames(t *testing.T, count int) ([]string, []*ax25.Packet) {
	t.Helper()

	var texts = make([]string, 0, count)
	var frames = make([]*ax25.Packet, 0, count)

	for i := range count {
		var text = fmt.Sprintf("Q1TEST>Q2TEST,WIDE1-1:>Frame %02d, long enough for the noise to have a go at it", i)

		var pp = ax25.FromText(text, true)
		require.NotNil(t, pp)

		texts = append(texts, text)
		frames = append(frames, pp)
	}

	return texts, frames
}

// What the tone generator sends as AFSK, each demodulator profile decodes
// back, with one slicer or several, at the common sample rates, and when the
// audio is decimated before demodulating - asked for, or chosen for 300 baud.
func TestDemodAFSKRoundTrip(t *testing.T) {
	t.Parallel()

	for _, tc := range []struct {
		afskTestCase

		wantSlicers  int
		wantDecimate int
	}{
		{afskTestCase{"A, single slicer", 1200, 1200, 2200, 44100, "A-", 0}, 1, 1},
		{afskTestCase{"A, multiple slicers", 1200, 1200, 2200, 44100, "A+", 0}, MAX_SLICERS, 1},
		{afskTestCase{"B, single slicer", 1200, 1200, 2200, 44100, "B-", 0}, 1, 3},
		{afskTestCase{"B, multiple slicers", 1200, 1200, 2200, 44100, "B+", 0}, MAX_SLICERS, 3},
		{afskTestCase{"A at 48kHz", 1200, 1200, 2200, 48000, "A-", 0}, 1, 1},
		{afskTestCase{"A at 48kHz, decimated", 1200, 1200, 2200, 48000, "A-", 3}, 1, 3},
		{afskTestCase{"A at 300 baud", 300, 1600, 1800, 48000, "A-", 0}, 1, 3},
		{afskTestCase{"B at 300 baud", 300, 1600, 1800, 48000, "B-", 0}, 1, 3},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			var texts, frames = afskTestFrames(t, 2)

			var samples = generateFrames(t, tc.radioConfig(), frames)

			var got, receiver = demodulateFrames(t, tc.radioConfig(), samples)

			require.Len(t, got, len(texts))

			for i, pp := range got {
				assert.Equal(t, texts[i], pp.FormatAddrs()+string(pp.Info()))
			}

			var d = receiver.demods[0]
			require.NotNil(t, d)

			assert.Equal(t, tc.wantSlicers, d.NumSlicers())
			assert.Equal(t, tc.wantDecimate, d.Decimate())
		})
	}
}

// Near where noise starts to win, each way of demodulating still gets at
// least as many frames through as it did when this test was written.  The
// noise is the same every run, so the counts are too: a change to the
// demodulator that should leave its output alone, such as rearranging a
// filter's arithmetic for speed, keeps them, and one that loses frames fails
// here.  One that gets more through can raise the count.
func TestDemodAFSKInNoise(t *testing.T) {
	t.Parallel()

	const sent = 20

	for _, tc := range []struct {
		afskTestCase

		noise float64 // Standard deviation, against a tone generator amplitude of 50.
		least int
	}{
		{afskTestCase{"A, single slicer", 1200, 1200, 2200, 44100, "A-", 0}, 14000, 14},
		{afskTestCase{"A, multiple slicers", 1200, 1200, 2200, 44100, "A+", 0}, 14000, 16},
		{afskTestCase{"B, single slicer", 1200, 1200, 2200, 44100, "B-", 0}, 14000, 13},
		{afskTestCase{"B, multiple slicers", 1200, 1200, 2200, 44100, "B+", 0}, 14000, 15},
		{afskTestCase{"A at 48kHz", 1200, 1200, 2200, 48000, "A-", 0}, 14000, 18},
		{afskTestCase{"A at 48kHz, decimated", 1200, 1200, 2200, 48000, "A-", 3}, 14000, 17},
		{afskTestCase{"A at 300 baud", 300, 1600, 1800, 48000, "A-", 0}, 30000, 17},
		{afskTestCase{"B at 300 baud", 300, 1600, 1800, 48000, "B-", 0}, 30000, 17},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			var texts, frames = afskTestFrames(t, sent)

			var samples = generateFrames(t, tc.radioConfig(), frames)

			var rng = rand.New(rand.NewPCG(1, 2))
			for i := range samples {
				samples[i] += int(rng.NormFloat64() * tc.noise)
			}

			var got, _ = demodulateFrames(t, tc.radioConfig(), samples)

			t.Logf("decoded %d of %d", len(got), sent)

			assert.GreaterOrEqual(t, len(got), tc.least)
			assert.Less(t, len(got), sent, "the noise is meant to cost some frames")

			// Whatever got through is what was sent: the noise never forges a frame.
			for _, pp := range got {
				assert.Contains(t, texts, pp.FormatAddrs()+string(pp.Info()))
			}
		})
	}
}

// genBPSKPackets writes frames numbered packets of BPSK at baud to a new .WAV
// file, as "samoyed-gen_packets -B baud -k -n frames -r samplesPerSec" would,
// and returns its name.  noisy adds more noise to each frame than the one
// before.
func genBPSKPackets(t *testing.T, baud int, samplesPerSec int, frames int, noisy bool) string {
	t.Helper()

	var wav = filepath.Join(t.TempDir(), "bpsk.wav")

	var flags = pflag.NewFlagSet("gen_packets", pflag.ContinueOnError)
	var modem = AddGenPacketsModemFlags(flags)
	require.NoError(t, flags.Parse([]string{"-B", strconv.Itoa(baud), "-k"}))

	var opts = newGenPacketsOptions()
	opts.Modem = modem
	opts.SampleRate = samplesPerSec

	var g, err = NewGenPackets(opts, wav)
	require.NoError(t, err)

	g.SendNumbered(frames, noisy)
	require.NoError(t, g.Close())

	return wav
}

// decodeBPSK decodes wav as BPSK at baud with demodulator profile, as
// "samoyed-atest -B baud -k -P profile" would, and returns how many frames it
// found.
func decodeBPSK(t *testing.T, wav string, baud int, profile string) int {
	t.Helper()

	var flags = pflag.NewFlagSet("atest", pflag.ContinueOnError)
	var modem = AddModemFlags(flags, true)
	require.NoError(t, flags.Parse([]string{"-B", strconv.Itoa(baud), "-k", "-P", profile}))

	var opts = atestTestOptions()
	opts.Modem = modem

	var atest, err = NewAtest(opts)
	require.NoError(t, err)

	var result, decodeErr = atest.DecodeFile(wav)
	require.NoError(t, decodeErr)

	return result.PacketsDecoded
}

// The self correlating BPSK demodulator, profile M, keeps up with the one
// that mixes with a local oscillator, profile N, as the noise rises.  Its
// taps used to be placed as fractions of a symbol, which put them in
// quadrature only for some ratios of carrier to symbol rate; at 1200 bit/s
// it decoded 26 of these 50 frames to N's 40 at 1800 Hz, and 18 to N's 39 at
// 1500 Hz.
func TestBPSKSelfCorrelationKeepsUpWithLocalOscillator(t *testing.T) {
	t.Parallel()

	var wav = genBPSKPackets(t, 1200, 44100, 50, true)

	var correlated = decodeBPSK(t, wav, 1200, "M")
	var mixed = decodeBPSK(t, wav, 1200, "N")

	assert.GreaterOrEqual(t, correlated, mixed-5, "profile M decoded %d, profile N %d", correlated, mixed)
}

// Every BPSK demodulator profile, at each rate, decodes every frame of a
// clean signal from the BPSK modulator.
func TestBPSKRoundTripEveryProfile(t *testing.T) {
	t.Parallel()

	const frames = 5

	for _, baud := range []int{300, 1200} {
		var wav = genBPSKPackets(t, baud, 44100, frames, false)

		for _, profile := range []string{"L", "M", "N", "O"} {
			t.Run(fmt.Sprintf("%d/%s", baud, profile), func(t *testing.T) {
				t.Parallel()

				assert.Equal(t, frames, decodeBPSK(t, wav, baud, profile))
			})
		}
	}
}

// newBPSKTestRadioConfig is a BPSK channel at baud, sending with layer2, and
// demodulating with profile.
func newBPSKTestRadioConfig(baud int, layer2 phy.Layer2, profile string) *RadioConfig {
	var audioConfig = newTestRadioConfig(0, MODEM_BPSK, baud, 0, 0, 44100)
	audioConfig.adev[0].defined = 1
	audioConfig.achan[0].NumFreq = 1
	audioConfig.achan[0].Profiles = profile
	audioConfig.achan[0].fix_bits = RETRY_NONE
	audioConfig.achan[0].layer2_xmit = layer2
	audioConfig.achan[0].il2p_max_fec = 1
	audioConfig.achan[0].il2p_crc = true
	audioConfig.achan[0].fx25_strength = 16

	return audioConfig
}

// What the tone generator sends over BPSK, as AX.25, FX.25 or IL2P, the
// demodulator decodes back, at each of the NinoTNC's rates.
func TestBPSKLayer2RoundTrip(t *testing.T) {
	t.Parallel()

	for _, layer2 := range []phy.Layer2{LAYER2_AX25, LAYER2_FX25, LAYER2_IL2P} {
		for _, baud := range []int{300, 1200} {
			t.Run(fmt.Sprintf("%v/%d", layer2, baud), func(t *testing.T) {
				t.Parallel()

				var texts, frames = afskTestFrames(t, 2)

				var samples = generateFrames(t, newBPSKTestRadioConfig(baud, layer2, "N"), frames)

				var got, _ = demodulateFrames(t, newBPSKTestRadioConfig(baud, layer2, "N"), samples)

				require.Len(t, got, len(texts))

				for i, pp := range got {
					assert.Equal(t, texts[i], pp.FormatAddrs()+string(pp.Info()))
				}
			})
		}
	}
}

// ninoAX25Bits is the bits the NinoTNC sends, one a symbol, for AX.25 frame
// pp over BPSK, with flags either side: 1 where the phase holds, 0 where it
// reverses.  Its recordings, at
// https://github.com/ninocarrillo/modem-test-audio, show it G3RUH scrambles
// HDLC's NRZI line and sends the result as the phase itself.
func ninoAX25Bits(pp *ax25.Packet) []bool {
	var levels []int

	var line = linecode.NewEncoder(func(level int) { levels = append(levels, level) })
	var sender = hdlc.NewSender(line, 0)

	sender.SendFlags(32)
	sender.SendFrame(pp.Pack(), false)
	sender.SendFlags(16)

	var scrambler linecode.Scrambler

	var bits = make([]bool, 0, len(levels))
	var phase = 0

	for _, level := range levels {
		var next = scrambler.Scramble(level)
		bits = append(bits, next == phase)
		phase = next
	}

	return bits
}

// BPSK sends AX.25 as the NinoTNC does, symbol for symbol.
func TestBPSKSendsAX25AsNinoTNC(t *testing.T) {
	t.Parallel()

	var _, frames = afskTestFrames(t, 1)

	var tg, _, _ = newCapturingToneGenerator(MODEM_BPSK, 1200, 48000)

	var got []bool

	var line = linecode.NewEncoder(func(level int) {
		var before = tg.bpskSign

		tg.PutBit(level)

		got = append(got, tg.bpskSign == before)
	})
	var sender = hdlc.NewSender(line, 0)

	sender.SendFlags(32)
	sender.SendFrame(frames[0].Pack(), false)
	sender.SendFlags(16)

	assert.Equal(t, ninoAX25Bits(frames[0]), got)
}

// BPSK receives AX.25 as the NinoTNC sends it.
func TestBPSKReceivesAX25FromNinoTNC(t *testing.T) {
	t.Parallel()

	var texts, frames = afskTestFrames(t, 1)

	var sink = new(recordingReceiveSink)
	var receiver, receiverErr = multi_modem_init(newBPSKTestRadioConfig(1200, LAYER2_AX25, "N"), 0, 0, sink)
	require.NoError(t, receiverErr)

	var pll dwcore.PLLStats

	for _, bit := range ninoAX25Bits(frames[0]) {
		// The scrambled flag as the BPSK demodulator passes it.
		receiver.RecBit(dwcore.SlicerID{Channel: 0, Subchannel: 0, Slice: 0}, bit, MODEM_BPSK.LineScrambled(), &pll)
	}

	for range 2 * receiver.modems[0].processAge {
		receiver.ProcessSample(0, 0)
	}

	require.Len(t, sink.frames, 1)
	assert.Equal(t, texts[0], sink.frames[0].FormatAddrs()+string(sink.frames[0].Info()))
}
